namespace ghidra.app.plugin.core.functionwindow;

using static ghidra.framework.model.DomainObjectEvent;
using static ghidra.program.util.ProgramEvent;

using ghidra.app;
using ghidra.app.events;
using ghidra.app.plugin;
using ghidra.app.plugin;
using ghidra.app.services;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.framework.options;
